class Solution {
public:
    vector<vector<int>> validArrangement(vector<vector<int>>& pairs) {
        int n = pairs.size();
        unordered_map<int, vector<int>> adj;
        unordered_map<int, int> outDeg, inDeg;
        adj.reserve(n * 2);
        outDeg.reserve(n * 2);
        inDeg.reserve(n * 2);

        for (auto& p : pairs) {
            adj[p[0]].push_back(p[1]);
            outDeg[p[0]]++;
            inDeg[p[1]]++;
        }

        int start = pairs[0][0];
        for (auto& [node, od] : outDeg) {
            if (od - inDeg[node] == 1) {
                start = node;
                break;
            }
        }

        vector<int> path;
        path.reserve(n + 1);
        vector<int> stk;
        stk.reserve(n + 1);
        stk.push_back(start);

        while (!stk.empty()) {
            int u = stk.back();
            auto it = adj.find(u);
            if (it != adj.end() && !it->second.empty()) {
                int v = it->second.back();
                it->second.pop_back();
                stk.push_back(v);
            } else {
                path.push_back(u);
                stk.pop_back();
            }
        }

        reverse(path.begin(), path.end());

        vector<vector<int>> result;
        result.reserve(n);
        for (int i = 0; i + 1 < (int)path.size(); i++) {
            result.push_back({path[i], path[i + 1]});
        }
        return result;
    }
};
